package com.servicerca.mapper; import com.servicerca.dto.request.*;import com.servicerca.dto.user.*;import com.servicerca.model.*;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.Collectors;
@Component public class ApiMapper{
 public TradeResponse toTradeResponse(Trade t){return new TradeResponse(t.getId(),t.getCode(),t.getName(),t.getIcon());}
 public UserResponse toUserResponse(User u){return new UserResponse(u.getId(),u.getEmail(),u.getFullName(),u.getDniEncrypted()==null?null:"••••••"+u.getId().toString().substring(0,2),u.getPhone(),u.getPhotoUrl(),u.getLocality(),u.getLatitude(),u.getLongitude(),u.isOnboardingComplete(),u.isProfessionalEnabled(),u.isAvailable(),u.getRating(),u.getRatingCount(),u.getTrades().stream().map(this::toTradeResponse).collect(Collectors.toSet()));}
 public UserSummaryResponse toUserSummary(User u,boolean contact){return new UserSummaryResponse(u.getId(),u.getFullName(),u.getPhotoUrl(),u.getLocality(),u.getRating(),u.getRatingCount(),contact?u.getPhone():null);}
 public ApplicationResponse toApplicationResponse(ServiceApplication a,boolean contact){return new ApplicationResponse(a.getId(),toUserSummary(a.getProfessional(),contact),a.getStatus(),a.getMessage(),a.getCreatedAt());}
 public ServiceRequestResponse toServiceRequestResponse(ServiceRequest r,List<ServiceApplication> apps,User viewer){boolean contact=r.getSelectedApplication()!=null&&(r.getClient().getId().equals(viewer.getId())||r.getSelectedApplication().getProfessional().getId().equals(viewer.getId()));return new ServiceRequestResponse(r.getId(),toUserSummary(r.getClient(),contact),toTradeResponse(r.getTrade()),r.getTitle(),r.getDescription(),r.getLocality(),r.getLatitude(),r.getLongitude(),r.getUrgency(),r.getBudget(),r.getStatus(),r.getCreatedAt(),apps.stream().map(a->toApplicationResponse(a,contact&&a.getStatus()==ApplicationStatus.SELECTED)).toList(),r.getSelectedApplication()==null?null:toApplicationResponse(r.getSelectedApplication(),contact),r.isClientCompleted(),r.isProfessionalCompleted(),List.of());}
}
